cat > main.go << 'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/andybalholm/cascadia"
	"github.com/clbanning/mxj/v2"
	"github.com/urfave/cli/v2"
	"golang.org/x/net/html"
)

const Version = "1.4.0"

func main() {
	app := &cli.App{
		Name:  "xq",
		Usage: "Command-line XML and HTML beautifier and content extractor",
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:    "attr",
				Aliases: []string{"a"},
				Usage:   "Extract an attribute value instead of node content for provided CSS query",
			},
			&cli.BoolFlag{
				Name:    "color",
				Aliases: []string{"c"},
				Usage:   "Force colorful output",
			},
			&cli.BoolFlag{
				Name:  "compact",
				Usage: "Compact JSON output (no indentation)",
			},
			&cli.IntFlag{
				Name:    "depth",
				Aliases: []string{"d"},
				Value:   -1,
				Usage:   "Maximum nesting depth for JSON output (-1 for unlimited)",
			},
			&cli.StringFlag{
				Name:    "extract",
				Aliases: []string{"e"},
				Usage:   "Extract a single node from XML",
			},
			&cli.BoolFlag{
				Name:    "html",
				Aliases: []string{"m"},
				Usage:   "Use HTML formatter",
			},
			&cli.BoolFlag{
				Name:    "in-place",
				Aliases: []string{"i"},
				Usage:   "Format file in place",
			},
			&cli.IntFlag{
				Name:  "indent",
				Value: 2,
				Usage: "Use the given number of spaces for indentation",
			},
			&cli.BoolFlag{
				Name:    "json",
				Aliases: []string{"j"},
				Usage:   "Output the result as JSON",
			},
			&cli.BoolFlag{
				Name:  "no-color",
				Usage: "Disable colorful output",
			},
			&cli.BoolFlag{
				Name:    "node",
				Aliases: []string{"n"},
				Usage:   "Return the node content instead of text",
			},
			&cli.StringFlag{
				Name:    "query",
				Aliases: []string{"q"},
				Usage:   "Extract the node(s) using CSS selector",
			},
			&cli.BoolFlag{
				Name:  "tab",
				Usage: "Use tabs for indentation",
			},
			&cli.StringFlag{
				Name:    "xpath",
				Aliases: []string{"x"},
				Usage:   "Extract the node(s) from XML",
			},
			&cli.BoolFlag{
				Name:    "version",
				Aliases: []string{"v"},
				Usage:   "Print version information",
			},
		},
		Action: action,
	}

	if err := app.Run(os.Args); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func action(c *cli.Context) error {
	if c.Bool("version") {
		fmt.Printf("xq version %s\n", Version)
		return nil
	}

	var input []byte
	var err error

	// Read input from file or stdin
	if c.NArg() > 0 {
		filePath := c.Args().Get(0)
		input, err = os.ReadFile(filePath)
		if err != nil {
			return fmt.Errorf("error reading file: %w", err)
		}
	} else {
		input, err = io.ReadAll(os.Stdin)
		if err != nil {
			return fmt.Errorf("error reading stdin: %w", err)
		}
	}

	isHTML := c.Bool("html")
	useColor := c.Bool("color")
	noColor := c.Bool("no-color")
	useJSON := c.Bool("json")
	useNode := c.Bool("node")
	xpathExpr := c.String("xpath")
	extract := c.String("extract")
	cssQuery := c.String("query")
	attrName := c.String("attr")
	indent := c.Int("indent")
	useTab := c.Bool("tab")
	compact := c.Bool("compact")
	depth := c.Int("depth")
	inPlace := c.Bool("in-place")

	// Determine if we should use colors (not when piping unless forced)
	if !isatty(os.Stdout) && !useColor {
		noColor = true
	}

	// Process based on input type
	var output []byte

	if isHTML {
		// HTML processing
		doc, err := html.Parse(bytes.NewReader(input))
		if err != nil {
			return fmt.Errorf("error parsing HTML: %w", err)
		}

		if cssQuery != "" {
			// CSS selector extraction
			selector, err := cascadia.Parse(cssQuery)
			if err != nil {
				return fmt.Errorf("invalid CSS selector: %w", err)
			}

			nodes := cascadia.QueryAll(doc, selector)
			if len(nodes) == 0 {
				return nil
			}

			if attrName != "" {
				// Extract attribute values
				for i, node := range nodes {
					for _, attr := range node.Attr {
						if attr.Key == attrName {
							if i > 0 {
								output = append(output, '\n')
							}
							output = append(output, []byte(attr.Val)...)
							break
						}
					}
				}
			} else if useNode {
				// Return node content
				for i, node := range nodes {
					if i > 0 {
						output = append(output, '\n')
					}
					buf := &bytes.Buffer{}
					html.Render(buf, node)
					output = append(output, buf.Bytes()...)
				}
			} else {
				// Return text content
				for i, node := range nodes {
					if i > 0 {
						output = append(output, '\n')
					}
					text := extractTextContent(node)
					output = append(output, []byte(text)...)
				}
			}
		} else if useJSON {
			// HTML to JSON
			output, err = htmlToJSON(input, indent, compact, depth)
			if err != nil {
				return err
			}
		} else {
			// Format HTML
			output, err = formatHTML(input, indent, useTab, !noColor)
			if err != nil {
				return err
			}
		}
	} else {
		// XML processing
		if xpathExpr != "" || extract != "" {
			// XPath extraction
			expr := xpathExpr
			if extract != "" {
				expr = extract
			}
			isSingle := extract != ""

			output, err = extractXPath(input, expr, useNode, isSingle)
			if err != nil {
				return err
			}
		} else if useJSON {
			// XML to JSON
			output, err = xmlToJSON(input, indent, compact, depth)
			if err != nil {
				return err
			}
		} else {
			// Format XML
			output, err = formatXML(input, indent, useTab, !noColor)
			if err != nil {
				return err
			}
		}
	}

	// Handle in-place file writing
	if inPlace && c.NArg() > 0 {
		filePath := c.Args().Get(0)
		err := os.WriteFile(filePath, output, 0644)
		if err != nil {
			return fmt.Errorf("error writing file: %w", err)
		}
	} else {
		// Write to stdout
		_, err := os.Stdout.Write(output)
		if err != nil {
			return fmt.Errorf("error writing output: %w", err)
		}
	}

	return nil
}

func isatty(f *os.File) bool {
	stat, _ := f.Stat()
	return (stat.Mode() & os.ModeCharDevice) != 0
}

func formatXML(input []byte, indent int, useTab bool, useColor bool) ([]byte, error) {
	// Parse XML
	m, err := mxj.NewMapXml(input)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Pretty print
	var buf bytes.Buffer

	// Try to preserve XML declaration
	inputStr := string(input)
	lines := strings.Split(inputStr, "\n")
	if len(lines) > 0 && strings.Contains(lines[0], "<?xml") {
		buf.WriteString(lines[0])
		buf.WriteString("\n")
	}

	indentStr := ""
	if useTab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", indent)
	}

	xmlStr, err := m.XmlIndent("", indentStr)
	if err != nil {
		return nil, err
	}

	// Remove XML declaration if it was in the original (we already added it)
	xmlLines := strings.Split(xmlStr, "\n")
	startIdx := 0
	if len(xmlLines) > 0 && strings.Contains(xmlLines[0], "<?xml") {
		startIdx = 1
	}

	if useColor {
		// Apply colors
		for i := startIdx; i < len(xmlLines); i++ {
			colorizedLine := colorizeXML(xmlLines[i])
			buf.WriteString(colorizedLine)
			if i < len(xmlLines)-1 {
				buf.WriteString("\n")
			}
		}
	} else {
		for i := startIdx; i < len(xmlLines); i++ {
			buf.WriteString(xmlLines[i])
			if i < len(xmlLines)-1 {
				buf.WriteString("\n")
			}
		}
	}

	if len(xmlLines) > startIdx {
		buf.WriteString("\n")
	}

	return buf.Bytes(), nil
}

func formatHTML(input []byte, indent int, useTab bool, useColor bool) ([]byte, error) {
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return nil, fmt.Errorf("error parsing HTML: %w", err)
	}

	indentStr := ""
	if useTab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", indent)
	}

	var buf bytes.Buffer
	renderHTMLIndented(&buf, doc, 0, indentStr, useColor)

	return buf.Bytes(), nil
}

func renderHTMLIndented(w io.Writer, n *html.Node, depth int, indent string, useColor bool) {
	switch n.Type {
	case html.DocumentNode:
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			renderHTMLIndented(w, c, depth, indent, useColor)
		}
	case html.ElementNode:
		// Write opening tag
		indentStr := strings.Repeat(indent, depth)
		io.WriteString(w, indentStr)
		if useColor {
			io.WriteString(w, "\033[33m")
		}
		io.WriteString(w, "<"+n.Data)
		if len(n.Attr) > 0 {
			for _, attr := range n.Attr {
				io.WriteString(w, " ")
				if useColor {
					io.WriteString(w, "\033[0m\033[32m")
				}
				io.WriteString(w, attr.Key)
				if useColor {
					io.WriteString(w, "\033[0m\033[33m")
				}
				io.WriteString(w, "=")
				if useColor {
					io.WriteString(w, "\033[0m\033[32m")
				}
				io.WriteString(w, "\""+attr.Val+"\"")
				if useColor {
					io.WriteString(w, "\033[0m\033[33m")
				}
			}
		}
		io.WriteString(w, ">")
		if useColor {
			io.WriteString(w, "\033[0m")
		}

		// Check if we have only text content
		if hasOnlyText(n) {
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				renderHTMLIndented(w, c, depth, indent, useColor)
			}
			if useColor {
				io.WriteString(w, "\033[33m")
			}
			io.WriteString(w, "</"+n.Data+">")
			if useColor {
				io.WriteString(w, "\033[0m")
			}
			io.WriteString(w, "\n")
		} else {
			io.WriteString(w, "\n")
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				renderHTMLIndented(w, c, depth+1, indent, useColor)
			}
			if useColor {
				io.WriteString(w, "\033[33m")
			}
			io.WriteString(w, indentStr)
			io.WriteString(w, "</"+n.Data+">")
			if useColor {
				io.WriteString(w, "\033[0m")
			}
			io.WriteString(w, "\n")
		}
	case html.TextNode:
		text := strings.TrimSpace(n.Data)
		if text != "" {
			indentStr := strings.Repeat(indent, depth)
			io.WriteString(w, text)
		}
	}
}

func hasOnlyText(n *html.Node) bool {
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type != html.TextNode {
			return false
		}
	}
	return true
}

func extractTextContent(n *html.Node) string {
	var text strings.Builder
	var extractText func(*html.Node)
	extractText = func(node *html.Node) {
		if node.Type == html.TextNode {
			text.WriteString(strings.TrimSpace(node.Data))
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			extractText(c)
		}
	}
	extractText(n)
	return text.String()
}

func extractXPath(input []byte, expr string, returnNode bool, single bool) ([]byte, error) {
	m, err := mxj.NewMapXml(input)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Use XPath
	results, err := m.XpathQuery(expr)
	if err != nil {
		return nil, fmt.Errorf("error executing XPath: %w", err)
	}

	var buf bytes.Buffer

	if single && len(results) > 0 {
		// Return only first result for -e
		result := results[0]
		if returnNode {
			// Return as XML
			// Convert back to XML element
			if mapVal, ok := result.(map[string]interface{}); ok {
				xmlBytes, _ := json.MarshalIndent(mapVal, "", "  ")
				// This is a simplified approach - convert back to XML
				xmlStr, _ := mxj.Map(mapVal).Xml()
				buf.Write(xmlStr)
			}
		} else {
			// Return text content
			formatResultAsText(&buf, result)
		}
	} else {
		// Return all results
		for i, result := range results {
			if i > 0 {
				buf.WriteString("\n")
			}
			if returnNode {
				// Return as XML
				if mapVal, ok := result.(map[string]interface{}); ok {
					xmlStr, _ := mxj.Map(mapVal).Xml()
					buf.Write(xmlStr)
				}
			} else {
				// Return text content
				formatResultAsText(&buf, result)
			}
		}
	}

	result := buf.Bytes()
	if len(result) > 0 && result[len(result)-1] != '\n' {
		result = append(result, '\n')
	}

	return result, nil
}

func formatResultAsText(buf *bytes.Buffer, result interface{}) {
	switch v := result.(type) {
	case string:
		buf.WriteString(v)
	case map[string]interface{}:
		// For maps, extract text content
		if len(v) > 0 {
			// Try to find text content
			for key, val := range v {
				if key == "#text" {
					buf.WriteString(fmt.Sprint(val))
					return
				}
			}
			// If no #text, get string representation
			for _, val := range v {
				formatResultAsText(buf, val)
				return
			}
		}
	case []interface{}:
		for i, item := range v {
			if i > 0 {
				buf.WriteString("\n")
			}
			formatResultAsText(buf, item)
		}
	default:
		buf.WriteString(fmt.Sprint(v))
	}
}

func xmlToJSON(input []byte, indent int, compact bool, maxDepth int) ([]byte, error) {
	m, err := mxj.NewMapXml(input)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Apply depth limiting if needed
	if maxDepth > 0 {
		m = limitMapDepth(m, maxDepth, 0)
	}

	var jsonBytes []byte
	if compact {
		jsonBytes, err = json.Marshal(m)
	} else {
		indentStr := strings.Repeat(" ", indent)
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	// Add newline at the end
	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlToJSON(input []byte, indent int, compact bool, maxDepth int) ([]byte, error) {
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return nil, fmt.Errorf("error parsing HTML: %w", err)
	}

	// Convert HTML to map
	m := htmlNodeToMap(doc)

	// Apply depth limiting if needed
	if maxDepth > 0 {
		m = limitMapDepth(m.(map[string]interface{}), maxDepth, 0)
	}

	var jsonBytes []byte
	if compact {
		jsonBytes, err = json.Marshal(m)
	} else {
		indentStr := strings.Repeat(" ", indent)
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	// Add newline at the end
	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlNodeToMap(n *html.Node) interface{} {
	switch n.Type {
	case html.DocumentNode:
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode {
				return map[string]interface{}{
					c.Data: htmlNodeToMap(c),
				}
			}
		}
		return nil
	case html.ElementNode:
		m := make(map[string]interface{})

		// Add attributes
		for _, attr := range n.Attr {
			m["@"+attr.Key] = attr.Val
		}

		// Add child elements
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode {
				child := htmlNodeToMap(c)
				if existing, ok := m[c.Data]; ok {
					// Convert to array
					if arr, isArr := existing.([]interface{}); isArr {
						m[c.Data] = append(arr, child)
					} else {
						m[c.Data] = []interface{}{existing, child}
					}
				} else {
					m[c.Data] = child
				}
			} else if c.Type == html.TextNode {
				text := strings.TrimSpace(c.Data)
				if text != "" {
					m["#text"] = text
				}
			}
		}

		return m
	case html.TextNode:
		text := strings.TrimSpace(n.Data)
		if text != "" {
			return text
		}
		return nil
	}
	return nil
}

func limitMapDepth(m interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		// At max depth, return string representation
		return fmt.Sprint(m)
	}

	switch v := m.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, val := range v {
			result[k] = limitMapDepth(val, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(v))
		for i, val := range v {
			result[i] = limitMapDepth(val, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}

func colorizeXML(line string) string {
	// Simple colorization of XML tags
	var result strings.Builder
	inTag := false
	inAttrKey := false
	inAttrValue := false

	for i := 0; i < len(line); i++ {
		ch := line[i]
		if ch == '<' {
			result.WriteString("\033[33m")
			result.WriteByte(ch)
			inTag = true
		} else if ch == '>' && inTag {
			result.WriteByte(ch)
			result.WriteString("\033[0m")
			inTag = false
		} else if inTag && ch == '=' {
			result.WriteString("\033[32m")
			result.WriteByte(ch)
		} else if inTag && ch == '"' {
			result.WriteString("\033[32m")
			result.WriteByte(ch)
			result.WriteString("\033[0m\033[33m")
		} else {
			result.WriteByte(ch)
		}
	}

	if inTag {
		result.WriteString("\033[0m")
	}

	return result.String()
}
