	useJSON := c.Bool("json")
	useNode := c.Bool("node")
	xpathExpr := c.String("xpath")
	extract := c.String("extract")
	cssQuery := c.String("query")
	attrName := c.String("attr")
	indent := c.Int("indent")
	useTab := c.Bool("tab")
	compact := c.Bool("compact")
	depth := c.Int("depth")
	inPlace := c.Bool("in-place")

	// Determine if we should use colors (not when piping unless forced)
	if !isatty(os.Stdout) && !useColor {
