			}

			nodes := cascadia.QueryAll(doc, selector)
			if len(nodes) == 0 {
				return nil
			}

			if attrName != "" {
				// Extract attribute values
				for i, node := range nodes {
					for _, attr := range node.Attr {
						if attr.Key == attrName {
