				}
			} else if useNode {
				// Return node content
				for i, node := range nodes {
					if i > 0 {
						output = append(output, '\n')
					}
					buf := &bytes.Buffer{}
					html.Render(buf, node)
					output = append(output, buf.Bytes()...)
				}
			} else {
