			io.WriteString(w, "\n")
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				renderHTMLIndented(w, c, depth+1, indent, useColor)
			}
			if useColor {
				io.WriteString(w, "\033[33m")
			}
			io.WriteString(w, indentStr)
			io.WriteString(w, "</"+n.Data+">")
			if useColor {
				io.WriteString(w, "\033[0m")
			}
			io.WriteString(w, "\n")
		}
	case html.TextNode:
		text := strings.TrimSpace(n.Data)
		if text != "" {
			indentStr := strings.Repeat(indent, depth)
			io.WriteString(w, text)
		}
	}
}

func hasOnlyText(n *html.Node) bool {
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type != html.TextNode {
			return false
		}
	}
	return true
}

func extractTextContent(n *html.Node) string {
	var text strings.Builder
	var extractText func(*html.Node)
	extractText = func(node *html.Node) {
		if node.Type == html.TextNode {
			text.WriteString(strings.TrimSpace(node.Data))
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			extractText(c)
		}
	}
	extractText(n)
	return text.String()
}

func extractXPath(input []byte, expr string, returnNode bool, single bool) ([]byte, error) {
	m, err := mxj.NewMapXml(input)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Use XPath
	results, err := m.XpathQuery(expr)
	if err != nil {
		return nil, fmt.Errorf("error executing XPath: %w", err)
	}

	var buf bytes.Buffer

	if single && len(results) > 0 {
		// Return only first result for -e
		result := results[0]
		if returnNode {
			// Return as XML
			// Convert back to XML element
			if mapVal, ok := result.(map[string]interface{}); ok {
				xmlBytes, _ := json.MarshalIndent(mapVal, "", "  ")
				// This is a simplified approach - convert back to XML
				xmlStr, _ := mxj.Map(mapVal).Xml()
				buf.Write(xmlStr)
			}
		} else {
			// Return text content
			formatResultAsText(&buf, result)
		}
	} else {
		// Return all results
		for i, result := range results {
			if i > 0 {
				buf.WriteString("\n")
			}
			if returnNode {
				// Return as XML
				if mapVal, ok := result.(map[string]interface{}); ok {
					xmlStr, _ := mxj.Map(mapVal).Xml()
					buf.Write(xmlStr)
				}
			} else {
				// Return text content
				formatResultAsText(&buf, result)
			}
		}
	}

	result := buf.Bytes()
	if len(result) > 0 && result[len(result)-1] != '\n' {
		result = append(result, '\n')
	}

	return result, nil
}

func formatResultAsText(buf *bytes.Buffer, result interface{}) {
	switch v := result.(type) {
	case string:
		buf.WriteString(v)
	case map[string]interface{}:
		// For maps, extract text content
		if len(v) > 0 {
			// Try to find text content
			for key, val := range v {
				if key == "#text" {
					buf.WriteString(fmt.Sprint(val))
					return
				}
			}
			// If no #text, get string representation
			for _, val := range v {
				formatResultAsText(buf, val)
				return
			}
		}
	case []interface{}:
		for i, item := range v {
			if i > 0 {
				buf.WriteString("\n")
			}
			formatResultAsText(buf, item)
		}
	default:
		buf.WriteString(fmt.Sprint(v))
	}
}

func xmlToJSON(input []byte, indent int, compact bool, maxDepth int) ([]byte, error) {
	m, err := mxj.NewMapXml(input)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Apply depth limiting if needed
	if maxDepth > 0 {
		m = limitMapDepth(m, maxDepth, 0)
	}

	var jsonBytes []byte
	if compact {
		jsonBytes, err = json.Marshal(m)
	} else {
		indentStr := strings.Repeat(" ", indent)
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	// Add newline at the end
	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlToJSON(input []byte, indent int, compact bool, maxDepth int) ([]byte, error) {
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return nil, fmt.Errorf("error parsing HTML: %w", err)
	}

	// Convert HTML to map
	m := htmlNodeToMap(doc)

	// Apply depth limiting if needed
	if maxDepth > 0 {
		m = limitMapDepth(m.(map[string]interface{}), maxDepth, 0)
	}

	var jsonBytes []byte
	if compact {
		jsonBytes, err = json.Marshal(m)
	} else {
		indentStr := strings.Repeat(" ", indent)
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	// Add newline at the end
	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlNodeToMap(n *html.Node) interface{} {
	switch n.Type {
	case html.DocumentNode:
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode {
				return map[string]interface{}{
					c.Data: htmlNodeToMap(c),
				}
			}
		}
		return nil
	case html.ElementNode:
		m := make(map[string]interface{})

		// Add attributes
		for _, attr := range n.Attr {
			m["@"+attr.Key] = attr.Val
		}

		// Add child elements
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode {
				child := htmlNodeToMap(c)
				if existing, ok := m[c.Data]; ok {
					// Convert to array
					if arr, isArr := existing.([]interface{}); isArr {
						m[c.Data] = append(arr, child)
					} else {
						m[c.Data] = []interface{}{existing, child}
					}
				} else {
					m[c.Data] = child
				}
			} else if c.Type == html.TextNode {
				text := strings.TrimSpace(c.Data)
				if text != "" {
					m["#text"] = text
				}
			}
		}

		return m
	case html.TextNode:
		text := strings.TrimSpace(n.Data)
		if text != "" {
			return text
		}
		return nil
	}
	return nil
}

func limitMapDepth(m interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		// At max depth, return string representation
		return fmt.Sprint(m)
	}

	switch v := m.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, val := range v {
			result[k] = limitMapDepth(val, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(v))
		for i, val := range v {
			result[i] = limitMapDepth(val, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}

func colorizeXML(line string) string {
	// Simple colorization of XML tags
	var result strings.Builder
	inTag := false
	inAttrKey := false
	inAttrValue := false

	for i := 0; i < len(line); i++ {
		ch := line[i]
		if ch == '<' {
			result.WriteString("\033[33m")
			result.WriteByte(ch)
			inTag = true
		} else if ch == '>' && inTag {
			result.WriteByte(ch)
			result.WriteString("\033[0m")
			inTag = false
		} else if inTag && ch == '=' {
			result.WriteString("\033[32m")
			result.WriteByte(ch)
		} else if inTag && ch == '"' {
			result.WriteString("\033[32m")
			result.WriteByte(ch)
			result.WriteString("\033[0m\033[33m")
		} else {
			result.WriteByte(ch)
		}
	}

	if inTag {
		result.WriteString("\033[0m")
	}

	return result.String()
}
