func formatXMLElement(w *bytes.Buffer, m map[string]interface{}, depth int, indent string, useColor bool) {
	indentStr := strings.Repeat(indent, depth)
	nextIndentStr := strings.Repeat(indent, depth+1)

	for key, value := range m {
		// Write opening tag
		if useColor {
			w.WriteString("\033[33m")
		}
		w.WriteString(indentStr + "<" + key)

		// Handle attributes
		if attrs, ok := value.(map[string]interface{}); ok {
			if _, hasAttrs := attrs["-attrs"]; hasAttrs {
				if attrsMap, ok := attrs["-attrs"].(map[string]interface{}); ok {
					for attrKey, attrVal := range attrsMap {
						w.WriteString(" " + attrKey + "=")
						if useColor {
							w.WriteString("\033[0m\033[32m")
						}
						w.WriteString("\"" + fmt.Sprint(attrVal) + "\"")
						if useColor {
							w.WriteString("\033[0m\033[33m")
						}
					}
				}
			}
		}

		if useColor {
			w.WriteString("\033[0m")
		}

		// Write closing tag part
		if useColor {
			w.WriteString("\033[33m")
		}
		w.WriteString(">")
		if useColor {
			w.WriteString("\033[0m")
		}
		w.WriteString("\n")

		// Write child content
		if attrs, ok := value.(map[string]interface{}); ok {
			if text, hasText := attrs["#text"]; hasText {
				w.WriteString(nextIndentStr + fmt.Sprint(text) + "\n")
			}
			for childKey, childVal := range attrs {
				if childKey != "-attrs" && childKey != "#text" {
					if childMap, ok := childVal.(map[string]interface{}); ok {
						formatXMLElement(w, childMap, depth+1, indent, useColor)
					}
				}
			}
		}

		// Write closing tag
		if useColor {
			w.WriteString("\033[33m")
		}
		w.WriteString(indentStr + "</" + key + ">")
		if useColor {
			w.WriteString("\033[0m")
		}
		w.WriteString("\n")
	}
}

func formatHTML(input []byte, config Config) ([]byte, error) {
	// For now, just format as is - we'll handle this with regex parsing
	var output bytes.Buffer

	lines := strings.Split(string(input), "\n")
