func parseHTMLElement(content string, tag string) interface{} {
	// Extract element content
	pattern := `<` + regexp.QuoteMeta(tag) + `[^>]*>(.*?)</` + regexp.QuoteMeta(tag) + `>`
	re := regexp.MustCompile(pattern)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return nil
	}

	innerContent := match[1]
	m := make(map[string]interface{})

	// Find child elements
	re = regexp.MustCompile(`<(\w+)[^>]*>`)
	matches := re.FindAllStringSubmatch(innerContent, -1)

	for _, childMatch := range matches {
		if len(childMatch) >= 2 {
			childTag := childMatch[1]
			if childTag != "" {
				childContent := parseHTMLElement(innerContent, childTag)
				if existing, exists := m[childTag]; exists {
					if arr, isArr := existing.([]interface{}); isArr {
						m[childTag] = append(arr, childContent)
					} else {
						m[childTag] = []interface{}{existing, childContent}
					}
				} else {
					m[childTag] = childContent
				}
			}
		}
	}

	// Extract text content if no child elements
	if len(m) == 0 {
		text := strings.TrimSpace(innerContent)
		if text != "" && !strings.Contains(text, "<") {
			return text
		}
	}

	if len(m) == 0 {
		return innerContent
	}

	return m
}

func limitDepth(v interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		return fmt.Sprint(v)
	}

	switch val := v.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, v := range val {
			result[k] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, v := range val {
			result[i] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}

