func formatXMLWithRegex(input []byte, config Config) ([]byte, error) {
	// Simple XML formatter using regex
	inputStr := string(input)
	var output bytes.Buffer

	// Extract XML declaration
	declPattern := regexp.MustCompile(`<\?xml[^?]*\?>`)
	declMatch := declPattern.FindString(inputStr)
	if declMatch != "" {
		output.WriteString(declMatch)
		output.WriteString("\n")
		// Remove it from the string for further processing
		inputStr = declPattern.ReplaceAllString(inputStr, "")
	}

	// Trim and format
	inputStr = strings.TrimSpace(inputStr)

	// Split into lines and format each
	indentStr := ""
	if config.Tab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", config.Indent)
	}

	depth := 0
	lines := strings.Split(inputStr, "\n")

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Count closing tags
		closingTags := strings.Count(trimmed, "</")
		if closingTags > 0 {
			depth -= closingTags
		}

		// Add indentation
		currentIndent := strings.Repeat(indentStr, depth)
		if config.NoColor {
			output.WriteString(currentIndent + trimmed + "\n")
		} else {
			output.WriteString(currentIndent + colorizeXML(trimmed) + "\n")
		}

		// Count opening tags (excluding self-closing and closing tags)
		openingTags := strings.Count(trimmed, "<") - closingTags - strings.Count(trimmed, "/>")
		depth += openingTags
	}

	return output.Bytes(), nil
}

func colorizeXML(line string) string {
	// ANSI color codes
	// 33m = yellow
	// 32m = green
	// 0m = reset
	var result strings.Builder

	i := 0
	for i < len(line) {
		if line[i] == '<' {
			// Check if closing tag
			if i+1 < len(line) && line[i+1] == '/' {
				result.WriteString("\033[33m</")
				i += 2
				// Find the tag name
				for i < len(line) && line[i] != '>' {
					result.WriteByte(line[i])
					i++
				}
				if i < len(line) {
					result.WriteString(">\033[0m")
					i++
				}
			} else {
				result.WriteString("\033[33m<")
				i++
				// Find tag name and attributes
				for i < len(line) && line[i] != '>' && line[i] != '/' {
					if line[i] == '=' {
						result.WriteString("\033[0m\033[32m")
						result.WriteByte(line[i])
						i++
						result.WriteString("\033[0m\033[33m")
					} else {
						result.WriteByte(line[i])
						i++
					}
				}
				// Handle closing > or />
				if i < len(line) {
					if line[i] == '/' {
						result.WriteByte(line[i])
						i++
					}
					if i < len(line) && line[i] == '>' {
						result.WriteString(">\033[0m")
						i++
					}
				}
			}
		} else {
			result.WriteByte(line[i])
			i++
		}
	}

	return result.String()
}

