func formatXML(input []byte, config Config) ([]byte, error) {
	// Extract XML declaration
	inputStr := string(input)
	var xmlDecl string

	declPattern := regexp.MustCompile(`<\?xml[^?]*\?>`)
	if match := declPattern.FindString(inputStr); match != "" {
		xmlDecl = match
		inputStr = declPattern.ReplaceAllString(inputStr, "")
	}

	inputStr = strings.TrimSpace(inputStr)

	// Build indentation string
	indentStr := ""
	if config.Tab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", config.Indent)
	}

	// Parse and rebuild with proper indentation
	var output bytes.Buffer

	if xmlDecl != "" {
		output.WriteString(xmlDecl)
		output.WriteString("\n")
	}

	// Simple recursive formatter
	depth := 0
	i := 0
	for i < len(inputStr) {
		// Find next tag
		tagStart := strings.IndexByte(inputStr[i:], '<')
		if tagStart == -1 {
			break
		}

		// Add text before tag
		if tagStart > 0 {
			text := strings.TrimSpace(inputStr[i : i+tagStart])
			if text != "" {
				// This is text content - add without indentation change
				continue
			}
		}

		i += tagStart
		tagEnd := strings.IndexByte(inputStr[i:], '>')
		if tagEnd == -1 {
			break
		}

		tag := inputStr[i : i+tagEnd+1]
		i += tagEnd + 1

		// Check tag type
		if strings.HasPrefix(tag, "<?") {
			// Processing instruction - skip
			continue
		} else if strings.HasPrefix(tag, "<!") {
			// Comment or doctype - skip
			continue
		} else if strings.HasPrefix(tag, "</") {
			// Closing tag
			depth--
			indent := strings.Repeat(indentStr, depth)
			if config.NoColor {
				output.WriteString(indent + tag + "\n")
			} else {
				output.WriteString(indent + colorizeXML(tag) + "\n")
			}
		} else if strings.HasSuffix(tag, "/>") {
			// Self-closing tag
			indent := strings.Repeat(indentStr, depth)
			if config.NoColor {
				output.WriteString(indent + tag + "\n")
			} else {
				output.WriteString(indent + colorizeXML(tag) + "\n")
			}
		} else {
			// Opening tag
			indent := strings.Repeat(indentStr, depth)
			if config.NoColor {
				output.WriteString(indent + tag + "\n")
			} else {
				output.WriteString(indent + colorizeXML(tag) + "\n")
			}
			depth++
		}
	}

	return output.Bytes(), nil
}

func colorizeXML(line string) string {
	// ANSI color codes
	var result strings.Builder

	i := 0
	for i < len(line) {
		if line[i] == '<' {
			result.WriteString("\033[33m<")
			i++

			// Find end of tag
			for i < len(line) && line[i] != '>' {
				if line[i] == '=' {
					result.WriteString("\033[0m\033[32m=\033[0m\033[33m")
					i++
				} else {
					result.WriteByte(line[i])
					i++
				}
			}

			if i < len(line) && line[i] == '>' {
				result.WriteString(">\033[0m")
				i++
			}
		} else {
			result.WriteByte(line[i])
			i++
		}
	}

	return result.String()
}

func formatHTML(input []byte, config Config) ([]byte, error) {
