	// Split into lines and format each
	indentStr := ""
	if config.Tab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", config.Indent)
	}

	depth := 0
	lines := strings.Split(inputStr, "\n")

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Count closing tags
		closingTags := strings.Count(trimmed, "</")
		if closingTags > 0 {
			depth -= closingTags
		}

		// Add indentation
		currentIndent := strings.Repeat(indentStr, depth)
		if config.NoColor {
			output.WriteString(currentIndent + trimmed + "\n")
		} else {
			output.WriteString(currentIndent + trimmed + "\n")
		}

		// Count opening tags
		openingTags := strings.Count(trimmed, "<") - closingTags - strings.Count(trimmed, "/>")
		depth += openingTags
	}

