func extractXPath(input []byte, expr string, returnNode bool, single bool) ([]byte, error) {
	// Simple XPath support for basic patterns
	var results []string

	// Parse XML manually
	content := string(input)

	if strings.Contains(expr, "//") {
		// Extract all matching tags
		tagName := strings.TrimPrefix(expr, "//")

		// Check if it's an attribute query
		if strings.Contains(tagName, "@") {
			parts := strings.Split(tagName, "@")
			basePath := parts[0]
			attrName := parts[1]

			// Find matching elements and extract attributes
			pattern := `<` + regexp.QuoteMeta(basePath) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, match[1])
				}
			}
		} else {
			// Extract text content
			pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>([^<]*)</` + regexp.QuoteMeta(tagName) + `>`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, strings.TrimSpace(match[1]))
				}
			}

			// If no results and returnNode is true, try to extract the whole element
			if len(results) == 0 && returnNode {
				pattern = `<` + regexp.QuoteMeta(tagName) + `[^>]*>.*?</` + regexp.QuoteMeta(tagName) + `>`
				re = regexp.MustCompile(pattern)
				matches := re.FindAllString(content, -1)
				for _, match := range matches {
					results = append(results, match)
				}
			}
		}
	} else if strings.HasPrefix(expr, "/") {
		// Absolute path
		parts := strings.Split(strings.TrimPrefix(expr, "/"), "/")

		if len(parts) >= 2 && strings.Contains(parts[len(parts)-1], "@") {
			// Attribute extraction
			attrParts := strings.Split(parts[len(parts)-1], "@")
			tagName := attrParts[0]
			attrName := attrParts[1]

			pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, match[1])
				}
			}
		}
	}

	var output bytes.Buffer
	if len(results) > 0 {
		if single {
			output.WriteString(results[0])
		} else {
			for i, result := range results {
				if i > 0 {
					output.WriteString("\n")
				}
				output.WriteString(result)
			}
		}
		output.WriteString("\n")
	}

	return output.Bytes(), nil
}

func extractCSSSelector(input []byte, selector string, attrName string, returnNode bool) ([]byte, error) {
	// Basic CSS selector support
	var results []string
	content := string(input)

	// Parse simple selectors like "p", "head > script", etc.
	parts := strings.Split(selector, " > ")
	tagName := strings.TrimSpace(parts[len(parts)-1])

	if attrName != "" {
		// Extract attribute value
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllStringSubmatch(content, -1)

		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, match[1])
			}
		}
	} else if returnNode {
		// Extract node content (with tags)
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>.*?</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllString(content, -1)
		results = matches
	} else {
		// Extract text content
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>([^<]*)</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllStringSubmatch(content, -1)

		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, strings.TrimSpace(match[1]))
			}
		}
	}

	var output bytes.Buffer
	for i, result := range results {
		if i > 0 {
			output.WriteString("\n")
		}
		output.WriteString(result)
	}

	if len(results) > 0 {
		output.WriteString("\n")
	}

	return output.Bytes(), nil
}

func xmlToJSON(input []byte, config Config) ([]byte, error) {
	// Parse XML and convert to map
	var m interface{}
	err := xml.Unmarshal(input, &m)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Apply depth limiting if needed
	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0)
	}

	var jsonBytes []byte
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		// Remove spaces after colons and commas for compact format
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlToJSON(input []byte, config Config) ([]byte, error) {
