		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, match[1])
			}
		}
	} else if returnNode {
		// Extract node content (with tags)
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>.*?</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllString(content, -1)
		results = matches
	} else {
		// Extract text content
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>([^<]*)</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllStringSubmatch(content, -1)

		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, strings.TrimSpace(match[1]))
			}
		}
	}

	var output bytes.Buffer
	for i, result := range results {
		if i > 0 {
			output.WriteString("\n")
		}
		output.WriteString(result)
	}

	if len(results) > 0 {
		output.WriteString("\n")
	}

	return output.Bytes(), nil
}

func xmlToJSON(input []byte, config Config) ([]byte, error) {
	// Parse XML and convert to map
	var m interface{}
	err := xml.Unmarshal(input, &m)
	if err != nil {
		return nil, fmt.Errorf("error parsing XML: %w", err)
	}

	// Apply depth limiting if needed
	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0)
	}

	var jsonBytes []byte
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		// Remove spaces after colons and commas for compact format
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlToJSON(input []byte, config Config) ([]byte, error) {
	// Simple HTML to JSON conversion
	m := parseHTMLToMap(string(input))

	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0).(map[string]interface{})
	}

	var jsonBytes []byte
	var err error
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func parseHTMLToMap(content string) map[string]interface{} {
	// Simple HTML parser - extract root element
	// Find first element
	re := regexp.MustCompile(`<(\w+)[^>]*>`)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return make(map[string]interface{})
	}

	rootTag := match[1]
	m := parseHTMLElement(content, rootTag)
	return map[string]interface{}{rootTag: m}
}

func parseHTMLElement(content string, tag string) interface{} {
	// Extract element content
	pattern := `<` + regexp.QuoteMeta(tag) + `[^>]*>(.*?)</` + regexp.QuoteMeta(tag) + `>`
	re := regexp.MustCompile(pattern)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return nil
	}

	innerContent := match[1]
	m := make(map[string]interface{})

	// Find child elements
	re = regexp.MustCompile(`<(\w+)[^>]*>`)
	matches := re.FindAllStringSubmatch(innerContent, -1)

	for _, childMatch := range matches {
		if len(childMatch) >= 2 {
			childTag := childMatch[1]
			if childTag != "" {
				childContent := parseHTMLElement(innerContent, childTag)
				if existing, exists := m[childTag]; exists {
					if arr, isArr := existing.([]interface{}); isArr {
						m[childTag] = append(arr, childContent)
					} else {
						m[childTag] = []interface{}{existing, childContent}
					}
				} else {
					m[childTag] = childContent
				}
			}
		}
	}

	// Extract text content if no child elements
	if len(m) == 0 {
		text := strings.TrimSpace(innerContent)
		if text != "" && !strings.Contains(text, "<") {
			return text
		}
	}

	if len(m) == 0 {
		return innerContent
	}

	return m
}

func limitDepth(v interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		return fmt.Sprint(v)
	}

	switch val := v.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, v := range val {
			result[k] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, v := range val {
			result[i] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}
