}

func main() {
	config := parseArgs()

	if config.HelpNeeded {
		printHelp()
		return
	}

	if config.Version {
		fmt.Printf("xq version %s\n", Version)
		return
	}

	var input []byte
	var err error

	// Read input from file or stdin
	if config.InputFile != "" {
		input, err = os.ReadFile(config.InputFile)
	} else {
		input, err = io.ReadAll(os.Stdin)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// Determine if we should use colors
	if !isatty(os.Stdout) && !config.Color {
		config.NoColor = true
	}

	// Process the input
	output, err := process(input, config)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	// Handle in-place file writing
	if config.InPlace && config.InputFile != "" {
		err := os.WriteFile(config.InputFile, output, 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing file: %v\n", err)
			os.Exit(1)
		}
	} else {
		os.Stdout.Write(output)
	}
}

func parseArgs() Config {
	config := Config{
		Depth:  -1,
		Indent: 2,
	}

	args := os.Args[1:]
	i := 0

	for i < len(args) {
		arg := args[i]

		if !strings.HasPrefix(arg, "-") {
			// Positional argument (input file)
			config.InputFile = arg
			i++
			continue
		}

		// Handle flags
		switch arg {
		case "-h", "--help":
			config.HelpNeeded = true
			return config
		case "-v", "--version":
			config.Version = true
			return config
		case "-c", "--color":
			config.Color = true
		case "--no-color":
			config.NoColor = true
		case "-m", "--html":
			config.Html = true
		case "-j", "--json":
			config.Json = true
		case "-n", "--node":
			config.Node = true
		case "-i", "--in-place":
			config.InPlace = true
		case "--tab":
			config.Tab = true
		case "--compact":
			config.Compact = true

		case "-a", "--attr":
			i++
			if i < len(args) {
				config.Attr = args[i]
			}
		case "-e", "--extract":
			i++
			if i < len(args) {
				config.Extract = args[i]
			}
		case "-q", "--query":
			i++
			if i < len(args) {
				config.Query = args[i]
			}
		case "-x", "--xpath":
			i++
			if i < len(args) {
				config.Xpath = args[i]
			}
		case "--indent":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &config.Indent)
			}
		case "-d", "--depth":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &config.Depth)
			}
		}

		i++
	}

	return config
}

