		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func parseXMLNode(decoder *xml.Decoder) *XMLNode {
	for {
		token, err := decoder.Token()
		if err != nil && err != io.EOF {
			return nil
		}

		if token == nil {
			break
		}

		switch se := token.(type) {
		case xml.StartElement:
			node := &XMLNode{
				Name:     se.Name.Local,
				Attrs:    make(map[string]string),
				Children: make(map[string]interface{}),
			}

			// Parse attributes
			for _, attr := range se.Attr {
				node.Attrs["@"+attr.Name.Local] = attr.Value
			}

			// Parse children and text
			for {
				innerToken, err := decoder.Token()
				if err != nil && err != io.EOF {
					break
				}

				if innerToken == nil {
					break
				}

				switch innerSe := innerToken.(type) {
				case xml.StartElement:
					// Nested element
					childNode := parseXMLNode(decoder)
					if childNode != nil {
						key := childNode.Name
						if existing, exists := node.Children[key]; exists {
							if arr, isArr := existing.([]interface{}); isArr {
								node.Children[key] = append(arr, childNode)
							} else {
								node.Children[key] = []interface{}{existing, childNode}
							}
						} else {
							node.Children[key] = childNode
						}
					}
				case xml.CharData:
					text := strings.TrimSpace(string(innerSe))
					if text != "" {
						node.Text = text
					}
				case xml.EndElement:
					// End of this element
					return node
				}
			}

			return node
		}
	}

	return nil
}

func nodeToMap(node *XMLNode) map[string]interface{} {
	result := make(map[string]interface{})
	nodeData := make(map[string]interface{})

	// Add attributes
	for k, v := range node.Attrs {
		nodeData[k] = v
	}

	// Add text content if present
	if node.Text != "" {
		if len(node.Attrs) > 0 || len(node.Children) > 0 {
			nodeData["#text"] = node.Text
		} else {
			return map[string]interface{}{node.Name: node.Text}
		}
	}

	// Add children
	for k, v := range node.Children {
		nodeData[k] = convertChildValue(v)
	}

	result[node.Name] = nodeData
	return result
}

func convertChildValue(v interface{}) interface{} {
	switch val := v.(type) {
	case *XMLNode:
		nodeData := make(map[string]interface{})
		for k, attrV := range val.Attrs {
			nodeData[k] = attrV
		}
		if val.Text != "" {
			if len(nodeData) > 0 {
				nodeData["#text"] = val.Text
			} else {
				return val.Text
			}
		}
		for k, childV := range val.Children {
			nodeData[k] = convertChildValue(childV)
		}
		return nodeData
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, item := range val {
			result[i] = convertChildValue(item)
		}
		return result
	default:
		return v
	}
}

func htmlToJSON(input []byte, config Config) ([]byte, error) {
	// Simple HTML to JSON conversion
	m := parseHTMLToMap(string(input))

	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0).(map[string]interface{})
	}

	var jsonBytes []byte
	var err error
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func parseHTMLToMap(content string) map[string]interface{} {
	// Simple HTML parser - extract root element
	// Find first element
	re := regexp.MustCompile(`<(\w+)[^>]*>`)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return make(map[string]interface{})
	}

	rootTag := match[1]
	m := parseHTMLElement(content, rootTag)
	return map[string]interface{}{rootTag: m}
}

func parseHTMLElement(content string, tag string) interface{} {
	// Extract element content
	pattern := `<` + regexp.QuoteMeta(tag) + `[^>]*>(.*?)</` + regexp.QuoteMeta(tag) + `>`
	re := regexp.MustCompile(pattern)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return nil
	}

	innerContent := match[1]
	m := make(map[string]interface{})

	// Find child elements
	re = regexp.MustCompile(`<(\w+)[^>]*>`)
	matches := re.FindAllStringSubmatch(innerContent, -1)

	for _, childMatch := range matches {
		if len(childMatch) >= 2 {
			childTag := childMatch[1]
			if childTag != "" {
				childContent := parseHTMLElement(innerContent, childTag)
				if existing, exists := m[childTag]; exists {
					if arr, isArr := existing.([]interface{}); isArr {
						m[childTag] = append(arr, childContent)
					} else {
						m[childTag] = []interface{}{existing, childContent}
					}
				} else {
					m[childTag] = childContent
				}
			}
		}
	}

	// Extract text content if no child elements
	if len(m) == 0 {
		text := strings.TrimSpace(innerContent)
		if text != "" && !strings.Contains(text, "<") {
			return text
		}
	}

	if len(m) == 0 {
		return innerContent
	}

	return m
}

func limitDepth(v interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		return fmt.Sprint(v)
	}

	switch val := v.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, v := range val {
			result[k] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, v := range val {
			result[i] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}
