func parseXMLElement(content string, tag string, startIdx int) interface{} {
	// Find start of this element
	pattern := `<` + regexp.QuoteMeta(tag) + `([^>]*)>`
	re := regexp.MustCompile(pattern)
	match := re.FindStringIndex(content[startIdx:])
	if match == nil {
		return nil
	}

	startPos := startIdx + match[1]

	// Find end of this element
	endPattern := `</` + regexp.QuoteMeta(tag) + `>`
	endRe := regexp.MustCompile(endPattern)
	endMatch := endRe.FindStringIndex(content[startPos:])
	if endMatch == nil {
		return nil
	}

	endPos := startPos + endMatch[0]
	innerContent := content[startPos:endPos]

	// Parse inner content
	result := make(map[string]interface{})

	// Check for attributes in opening tag
	attrPattern := `<` + regexp.QuoteMeta(tag) + `\s+([^>]*?)>`
	attrRe := regexp.MustCompile(attrPattern)
	attrMatch := attrRe.FindString(content[startIdx : startIdx+match[1]])
	if attrMatch != "" {
		// Extract attributes
		attrs := parseAttributes(attrMatch)
		for k, v := range attrs {
			result["@"+k] = v
		}
	}

	// Find child elements
	childPattern := `<(\w+)([^/>]*?)>(.*?)</\1>`
	childRe := regexp.MustCompile(childPattern)
	children := childRe.FindAllString(innerContent, -1)

	if len(children) > 0 {
		for _, child := range children {
			// Extract tag name
			childTagPattern := `<(\w+)`
			childTagRe := regexp.MustCompile(childTagPattern)
			childTagMatch := childTagRe.FindStringSubmatch(child)
			if len(childTagMatch) > 1 {
				childTag := childTagMatch[1]
				// Find the value recursively
				childValue := parseXMLElement(innerContent, childTag, 0)
				if existing, exists := result[childTag]; exists {
					if arr, isArr := existing.([]interface{}); isArr {
						result[childTag] = append(arr, childValue)
					} else {
						result[childTag] = []interface{}{existing, childValue}
					}
				} else {
					result[childTag] = childValue
				}
			}
		}
	}

	// If no children, extract text content
	if len(children) == 0 {
		text := strings.TrimSpace(innerContent)
		if text != "" {
			if len(result) > 0 {
				result["#text"] = text
			} else {
				return text
			}
		}
	}

	return result
}

func parseAttributes(tagStart string) map[string]string {
	attrs := make(map[string]string)
	// Simple regex to find key="value" pairs
	re := regexp.MustCompile(`(\w+)="([^"]*)"`)
	matches := re.FindAllStringSubmatch(tagStart, -1)
	for _, match := range matches {
		if len(match) > 2 {
			attrs[match[1]] = match[2]
		}
	}
	return attrs
}

