// SimpleXMLParser provides XML parsing without external libraries
type SimpleXMLParser struct {
	content string
	pos     int
}

// ParseXMLToMap parses XML string to map structure
func ParseXMLToMap(content string) map[string]interface{} {
	parser := &SimpleXMLParser{content: content, pos: 0}

	// Skip XML declaration and other prologue
	if strings.Contains(content, "<?xml") {
		endDecl := strings.Index(content, "?>")
		if endDecl != -1 {
			parser.pos = endDecl + 2
		}
	}

	// Skip whitespace
	for parser.pos < len(parser.content) && strings.ContainsAny(string(parser.content[parser.pos]), " \t\n\r") {
		parser.pos++
	}

	node := parser.parseElement()
	if node == nil {
		return nil
	}

	return map[string]interface{}{node.Name: nodeToMap(node)}
}

// XMLNode represents a parsed XML element
type XMLNode struct {
	Name     string
	Attrs    map[string]string
	Children []*XMLNode
	Text     string
}

func (p *SimpleXMLParser) parseElement() *XMLNode {
	if p.pos >= len(p.content) || p.content[p.pos] != '<' {
		return nil
	}

	// Find opening tag end
	tagEnd := strings.IndexByte(p.content[p.pos:], '>')
	if tagEnd == -1 {
		return nil
	}

	tagEnd += p.pos
	tagContent := p.content[p.pos+1 : tagEnd]

	// Check for closing tag or self-closing
	if strings.HasPrefix(tagContent, "/") {
		return nil // Closing tag
	}

	// Extract tag name
	parts := strings.Fields(tagContent)
	if len(parts) == 0 {
		return nil
	}

	node := &XMLNode{
		Name:  parts[0],
		Attrs: make(map[string]string),
	}

	// Check for self-closing
	if strings.HasSuffix(tagContent, "/") {
		p.pos = tagEnd + 1
		return node
	}

	// Parse attributes
	if len(parts) > 1 {
		attrStr := strings.Join(parts[1:], " ")
		node.Attrs = parseAttributes(attrStr)
	}

	p.pos = tagEnd + 1

	// Parse content
