				if endTagEnd != -1 {
					endTagContent := p.content[p.pos+2 : p.pos+endTagEnd]
					endTagName := strings.Fields(endTagContent)
					if len(endTagName) > 0 && endTagName[0] == tagStart {
						p.pos = p.pos + endTagEnd + 1
						break
					}
				}
