package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
)

const Version = "1.4.0"

type Config struct {
	Attr       string
	Color      bool
	Compact    bool
	Depth      int
	Extract    string
	Html       bool
	InPlace    bool
	Indent     int
	Json       bool
	NoColor    bool
	Node       bool
	Query      string
	Tab        bool
	Xpath      string
	Version    bool
	HelpNeeded bool
	InputFile  string
}

func main() {
	config := parseArgs()

	if config.HelpNeeded {
		printHelp()
		return
	}

	if config.Version {
		fmt.Printf("xq version %s\n", Version)
		return
	}

	var input []byte
	var err error

	// Read input from file or stdin
	if config.InputFile != "" {
		input, err = os.ReadFile(config.InputFile)
	} else {
		input, err = io.ReadAll(os.Stdin)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// Determine if we should use colors
	if !isatty(os.Stdout) && !config.Color {
		config.NoColor = true
	}

	// Process the input
	output, err := process(input, config)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	// Handle in-place file writing
	if config.InPlace && config.InputFile != "" {
		err := os.WriteFile(config.InputFile, output, 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing file: %v\n", err)
			os.Exit(1)
		}
	} else {
		os.Stdout.Write(output)
	}
}

func parseArgs() Config {
	config := Config{
		Depth:  -1,
		Indent: 2,
	}

	args := os.Args[1:]
	i := 0

	for i < len(args) {
		arg := args[i]

		if !strings.HasPrefix(arg, "-") {
			// Positional argument (input file)
			config.InputFile = arg
			i++
			continue
		}

		// Handle flags
		switch arg {
		case "-h", "--help":
			config.HelpNeeded = true
			return config
		case "-v", "--version":
			config.Version = true
			return config
		case "-c", "--color":
			config.Color = true
		case "--no-color":
			config.NoColor = true
		case "-m", "--html":
			config.Html = true
		case "-j", "--json":
			config.Json = true
		case "-n", "--node":
			config.Node = true
		case "-i", "--in-place":
			config.InPlace = true
		case "--tab":
			config.Tab = true
		case "--compact":
			config.Compact = true

		case "-a", "--attr":
			i++
			if i < len(args) {
				config.Attr = args[i]
			}
		case "-e", "--extract":
			i++
			if i < len(args) {
				config.Extract = args[i]
			}
		case "-q", "--query":
			i++
			if i < len(args) {
				config.Query = args[i]
			}
		case "-x", "--xpath":
			i++
			if i < len(args) {
				config.Xpath = args[i]
			}
		case "--indent":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &config.Indent)
			}
		case "-d", "--depth":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &config.Depth)
			}
		}

		i++
	}

	return config
}

func printHelp() {
	fmt.Println("Command-line XML and HTML beautifier and content extractor")
	fmt.Println()
	fmt.Println("Usage:")
	fmt.Println("  xq [flags]")
	fmt.Println()
	fmt.Println("Flags:")
	fmt.Println("  -a, --attr string      Extract an attribute value instead of node content for provided CSS query")
	fmt.Println("  -c, --color            Force colorful output")
	fmt.Println("      --compact          Compact JSON output (no indentation)")
	fmt.Println("  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)")
	fmt.Println("  -e, --extract string   Extract a single node from XML")
	fmt.Println("  -h, --help             Print this help message")
	fmt.Println("  -m, --html             Use HTML formatter")
	fmt.Println("  -i, --in-place         Format file in place")
	fmt.Println("      --indent int       Use the given number of spaces for indentation (default 2)")
	fmt.Println("  -j, --json             Output the result as JSON")
	fmt.Println("      --no-color         Disable colorful output")
	fmt.Println("  -n, --node             Return the node content instead of text")
	fmt.Println("  -q, --query string     Extract the node(s) using CSS selector")
	fmt.Println("      --tab              Use tabs for indentation")
	fmt.Println("  -v, --version          Print version information")
	fmt.Println("  -x, --xpath string     Extract the node(s) from XML")
}

func process(input []byte, config Config) ([]byte, error) {
	if config.Html {
		return processHTML(input, config)
	}
	return processXML(input, config)
}

func processXML(input []byte, config Config) ([]byte, error) {
	if config.Xpath != "" || config.Extract != "" {
		// XPath extraction
		expr := config.Xpath
		if config.Extract != "" {
			expr = config.Extract
		}

		return extractXPath(input, expr, config.Node, config.Extract != "")
	}

	if config.Json {
		return xmlToJSON(input, config)
	}

	return formatXMLSimple(input, config)
}

func processHTML(input []byte, config Config) ([]byte, error) {
	if config.Query != "" {
		// CSS selector extraction
		return extractCSSSelector(input, config.Query, config.Attr, config.Node)
	}

	if config.Json {
		return htmlToJSON(input, config)
	}

	return formatHTML(input, config)
}

func isatty(f *os.File) bool {
	stat, _ := f.Stat()
	return (stat.Mode() & os.ModeCharDevice) != 0
}

func formatXMLSimple(input []byte, config Config) ([]byte, error) {
	// Simple line-by-line formatter
	inputStr := string(input)
	lines := strings.Split(inputStr, "\n")

	indentStr := ""
	if config.Tab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", config.Indent)
	}

	var output bytes.Buffer
	depth := 0

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Check if this is a closing tag at the beginning
		if strings.HasPrefix(trimmed, "</") {
			depth--
		}

		// Write the line with indentation
		indent := strings.Repeat(indentStr, depth)
		if config.NoColor {
			output.WriteString(indent + trimmed + "\n")
		} else {
			output.WriteString(indent + colorizeXML(trimmed) + "\n")
		}

		// Check if this is an opening tag (but not closing or processing instruction)
		// Also check if it does NOT have a closing tag on the same line
		isOpeningTag := strings.HasPrefix(trimmed, "<") && 
			!strings.HasPrefix(trimmed, "</") &&
			!strings.HasPrefix(trimmed, "<?") &&
			!strings.HasPrefix(trimmed, "<!") &&
			!strings.HasSuffix(trimmed, "/>")

		// Check if there is NO closing tag on the same line
		if isOpeningTag && !strings.Contains(trimmed, "</") {
			depth++
		}
	}

	return output.Bytes(), nil
}

func colorizeXML(line string) string {
	// ANSI color codes
	var result strings.Builder

	i := 0
	for i < len(line) {
		if line[i] == '<' {
			result.WriteString("\033[33m<")
			i++

			// Find end of tag
			for i < len(line) && line[i] != '>' {
				if line[i] == '=' {
					result.WriteString("\033[0m\033[32m=\033[0m\033[33m")
					i++
				} else {
					result.WriteByte(line[i])
					i++
				}
			}

			if i < len(line) && line[i] == '>' {
				result.WriteString(">\033[0m")
				i++
			}
		} else {
			result.WriteByte(line[i])
			i++
		}
	}

	return result.String()
}

func formatHTML(input []byte, config Config) ([]byte, error) {
	inputStr := string(input)
	lines := strings.Split(inputStr, "\n")

	indentStr := ""
	if config.Tab {
		indentStr = "\t"
	} else {
		indentStr = strings.Repeat(" ", config.Indent)
	}

	var output bytes.Buffer
	depth := 0

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Check if this is a closing tag at the beginning
		if strings.HasPrefix(trimmed, "</") {
			depth--
		}

		// Write the line with indentation
		indent := strings.Repeat(indentStr, depth)
		output.WriteString(indent + trimmed + "\n")

		// Check if this is an opening tag
		isOpeningTag := strings.HasPrefix(trimmed, "<") && 
			!strings.HasPrefix(trimmed, "</") &&
			!strings.HasPrefix(trimmed, "<!") &&
			!strings.HasSuffix(trimmed, "/>")

		// Check if there is NO closing tag on the same line
		if isOpeningTag && !strings.Contains(trimmed, "</") {
			depth++
		}
	}

	return output.Bytes(), nil
}

func extractXPath(input []byte, expr string, returnNode bool, single bool) ([]byte, error) {
	// Simple XPath support for basic patterns
	var results []string

	// Parse XML manually
	content := string(input)

	if strings.Contains(expr, "//") {
		// Extract all matching tags
		tagName := strings.TrimPrefix(expr, "//")

		// Check if it's an attribute query
		if strings.Contains(tagName, "@") {
			parts := strings.Split(tagName, "@")
			basePath := parts[0]
			attrName := parts[1]

			// Find matching elements and extract attributes
			pattern := `<` + regexp.QuoteMeta(basePath) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, match[1])
				}
			}
		} else {
			// Extract text content
			pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>([^<]*)</` + regexp.QuoteMeta(tagName) + `>`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, strings.TrimSpace(match[1]))
				}
			}

			// If no results and returnNode is true, try to extract the whole element
			if len(results) == 0 && returnNode {
				pattern = `<` + regexp.QuoteMeta(tagName) + `[^>]*>.*?</` + regexp.QuoteMeta(tagName) + `>`
				re = regexp.MustCompile(pattern)
				matches := re.FindAllString(content, -1)
				for _, match := range matches {
					results = append(results, match)
				}
			}
		}
	} else if strings.HasPrefix(expr, "/") {
		// Absolute path
		parts := strings.Split(strings.TrimPrefix(expr, "/"), "/")

		if len(parts) >= 2 && strings.Contains(parts[len(parts)-1], "@") {
			// Attribute extraction
			attrParts := strings.Split(parts[len(parts)-1], "@")
			tagName := attrParts[0]
			attrName := attrParts[1]

			pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
			re := regexp.MustCompile(pattern)
			matches := re.FindAllStringSubmatch(content, -1)

			for _, match := range matches {
				if len(match) > 1 {
					results = append(results, match[1])
				}
			}
		}
	}

	var output bytes.Buffer
	if len(results) > 0 {
		if single {
			output.WriteString(results[0])
		} else {
			for i, result := range results {
				if i > 0 {
					output.WriteString("\n")
				}
				output.WriteString(result)
			}
		}
		output.WriteString("\n")
	}

	return output.Bytes(), nil
}

func extractCSSSelector(input []byte, selector string, attrName string, returnNode bool) ([]byte, error) {
	// Basic CSS selector support
	var results []string
	content := string(input)

	// Parse simple selectors like "p", "head > script", etc.
	parts := strings.Split(selector, " > ")
	tagName := strings.TrimSpace(parts[len(parts)-1])

	if attrName != "" {
		// Extract attribute value
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*` + regexp.QuoteMeta(attrName) + `\s*=\s*"([^"]*)"`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllStringSubmatch(content, -1)

		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, match[1])
			}
		}
	} else if returnNode {
		// Extract node content (with tags)
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>.*?</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllString(content, -1)
		results = matches
	} else {
		// Extract text content
		pattern := `<` + regexp.QuoteMeta(tagName) + `[^>]*>([^<]*)</` + regexp.QuoteMeta(tagName) + `>`
		re := regexp.MustCompile(pattern)
		matches := re.FindAllStringSubmatch(content, -1)

		for _, match := range matches {
			if len(match) > 1 {
				results = append(results, strings.TrimSpace(match[1]))
			}
		}
	}

	var output bytes.Buffer
	for i, result := range results {
		if i > 0 {
			output.WriteString("\n")
		}
		output.WriteString(result)
	}

	if len(results) > 0 {
		output.WriteString("\n")
	}

	return output.Bytes(), nil
}

func xmlToJSON(input []byte, config Config) ([]byte, error) {
	// Parse XML into a generic map structure
	contentStr := string(input)
	m := ParseXMLToMap(contentStr)

	if m == nil {
		return nil, fmt.Errorf("failed to parse XML")
	}

	// Apply depth limiting if needed
	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0).(map[string]interface{})
	}

	var jsonBytes []byte
	var err error
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		// Remove spaces after colons and commas for compact format
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func htmlToJSON(input []byte, config Config) ([]byte, error) {
	// Simple HTML to JSON conversion
	m := parseHTMLToMap(string(input))

	if config.Depth > 0 {
		m = limitDepth(m, config.Depth, 0).(map[string]interface{})
	}

	var jsonBytes []byte
	var err error
	if config.Compact {
		jsonBytes, err = json.Marshal(m)
		jsonStr := string(jsonBytes)
		jsonStr = strings.ReplaceAll(jsonStr, ": ", ":")
		jsonStr = strings.ReplaceAll(jsonStr, ", ", ",")
		jsonBytes = []byte(jsonStr)
	} else {
		indentStr := ""
		if config.Tab {
			indentStr = "\t"
		} else {
			indentStr = strings.Repeat(" ", config.Indent)
		}
		jsonBytes, err = json.MarshalIndent(m, "", indentStr)
	}

	if err != nil {
		return nil, fmt.Errorf("error marshaling JSON: %w", err)
	}

	jsonBytes = append(jsonBytes, '\n')
	return jsonBytes, nil
}

func parseHTMLToMap(content string) map[string]interface{} {
	// Simple HTML parser - extract root element
	// Find first element
	re := regexp.MustCompile(`<(\w+)[^>]*>`)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return make(map[string]interface{})
	}

	rootTag := match[1]
	m := parseHTMLElement(content, rootTag)
	return map[string]interface{}{rootTag: m}
}

func parseHTMLElement(content string, tag string) interface{} {
	// Extract element content
	pattern := `<` + regexp.QuoteMeta(tag) + `[^>]*>(.*?)</` + regexp.QuoteMeta(tag) + `>`
	re := regexp.MustCompile(pattern)
	match := re.FindStringSubmatch(content)

	if len(match) < 2 {
		return nil
	}

	innerContent := match[1]
	m := make(map[string]interface{})

	// Find child elements
	re = regexp.MustCompile(`<(\w+)[^>]*>`)
	matches := re.FindAllStringSubmatch(innerContent, -1)

	for _, childMatch := range matches {
		if len(childMatch) >= 2 {
			childTag := childMatch[1]
			if childTag != "" {
				childContent := parseHTMLElement(innerContent, childTag)
				if existing, exists := m[childTag]; exists {
					if arr, isArr := existing.([]interface{}); isArr {
						m[childTag] = append(arr, childContent)
					} else {
						m[childTag] = []interface{}{existing, childContent}
					}
				} else {
					m[childTag] = childContent
				}
			}
		}
	}

	// Extract text content if no child elements
	if len(m) == 0 {
		text := strings.TrimSpace(innerContent)
		if text != "" && !strings.Contains(text, "<") {
			return text
		}
	}

	if len(m) == 0 {
		return innerContent
	}

	return m
}

func limitDepth(v interface{}, maxDepth int, currentDepth int) interface{} {
	if currentDepth >= maxDepth {
		return fmt.Sprint(v)
	}

	switch val := v.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{})
		for k, v := range val {
			result[k] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, v := range val {
			result[i] = limitDepth(v, maxDepth, currentDepth+1)
		}
		return result
	default:
		return v
	}
}
